import React, { useEffect, useState } from "react";
import axios from "axios";
import { Html5QrcodeScanner } from "html5-qrcode";

function QRScanner() {

const [user,setUser] = useState(null);
const [message,setMessage] = useState("");

useEffect(()=>{

const scanner = new Html5QrcodeScanner(
"reader",
{
fps:10,
qrbox:{ width:250, height:250 },
aspectRatio:1.0,
facingMode:"environment"
},
false
);

scanner.render(

async (decodedText)=>{

console.log("QR SCANNED:",decodedText);

verifyUser(decodedText);

},

(error)=>{
// ignore scanning errors
}

);

},[]);

/* VERIFY USER */

const verifyUser = async(id)=>{

try{

const res = await axios.get(
`http://localhost:5000/verify-user/${id}`
);

if(res.data.success){

const user = res.data.user;

setUser(user);

setMessage("✅ VERIFIED");

/* SAVE ATTENDANCE */

await axios.post(
"http://localhost:5000/mark-attendance",
{
name:user.name,
event_id:user.event_id,
phone:user.phone
}
);

}else{

setMessage("❌ NOT REGISTERED");

}

}catch(err){

console.log(err);

setMessage("⚠️ SERVER ERROR");

}

};

return(

<div style={{padding:"20px"}}>

<h2>Admin QR Scanner</h2>

<div id="reader" style={{width:"350px"}}></div>

<h3>{message}</h3>

{user && (

<div>

<p>Name: {user.name}</p>
<p>College: {user.college_name}</p>
<p>Phone: {user.phone}</p>
<p>Event: {user.event_id}</p>

</div>

)}

</div>

);

}

export default QRScanner;
